import {
  addDoc,
  collection,
  deleteDoc,
  doc,
  getDocs,
  orderBy,
  query,
  serverTimestamp,
  Timestamp,
  updateDoc,
  where,
} from "firebase/firestore";
import type { ItineraryDay } from "../../features/admin/types";

export type CreateDayInput = {
  itineraryId: string;
  dayNumber: number;
  date: string;
  city: string;
  title?: string;
  notes?: string;
  createdBy: string;
};

export type UpdateDayInput = Partial<
  Pick<CreateDayInput, "date" | "city" | "title" | "notes">
> & { updatedBy: string };

async function getDb() {
  const { db } = await import("../../lib/firebase");
  return db;
}

export async function createDay(input: CreateDayInput): Promise<string> {
  const db = await getDb();
  const ref = await addDoc(collection(db, "itineraryDays"), {
    itineraryId: input.itineraryId,
    dayNumber: input.dayNumber,
    date: Timestamp.fromDate(new Date(input.date)),
    city: input.city,
    title: input.title ?? null,
    notes: input.notes ?? null,
    createdAt: serverTimestamp(),
    updatedAt: serverTimestamp(),
    createdBy: input.createdBy,
    updatedBy: null,
  });
  return ref.id;
}

export async function updateDay(id: string, input: UpdateDayInput): Promise<void> {
  const db = await getDb();
  const payload: Record<string, unknown> = { ...input, updatedAt: serverTimestamp() };
  if (input.date) {
    payload["date"] = Timestamp.fromDate(new Date(input.date));
    delete payload["date"];
    payload["date"] = Timestamp.fromDate(new Date(input.date));
  }
  await updateDoc(doc(db, "itineraryDays", id), payload);
}

export async function listDaysByItinerary(itineraryId: string): Promise<(ItineraryDay & { id: string })[]> {
  const db = await getDb();
  const q = query(
    collection(db, "itineraryDays"),
    where("itineraryId", "==", itineraryId),
    orderBy("dayNumber", "asc")
  );
  const snap = await getDocs(q);
  return snap.docs.map((d) => ({ id: d.id, ...(d.data() as ItineraryDay) }));
}

export async function deleteDay(id: string): Promise<void> {
  const db = await getDb();
  await deleteDoc(doc(db, "itineraryDays", id));
}
